package vn.iotstar.security; import lombok.Getter; import org.springframework.security.core.*; import org.springframework.security.core.userdetails.UserDetails; import vn.iotstar.entity.User; import java.util.*; @Getter public class CustomUserDetails implements UserDetails{private final Long id;private final String username,password;private final boolean enabled;private final Collection<? extends GrantedAuthority> authorities;public CustomUserDetails(User u){id=u.getId();username=u.getUsername();password=u.getPassword();enabled=u.isEnabled();authorities=List.of((GrantedAuthority)()->u.getRole().getName());}public Collection<? extends GrantedAuthority> getAuthorities(){return authorities;}public String getPassword(){return password;}public String getUsername(){return username;}public boolean isAccountNonExpired(){return true;}public boolean isAccountNonLocked(){return true;}public boolean isCredentialsNonExpired(){return true;}public boolean isEnabled(){return enabled;}}